package com.troday.api.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="notifications",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","event_key"})) public class Notification {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="user_id",nullable=false) private Long userId; @Column(nullable=false) private String type; @Column(nullable=false) private String title; @Lob @Column(nullable=false) private String content; @Column(name="resource_type") private String resourceType; @Column(name="resource_id") private Long resourceId; @Column(name="event_key",nullable=false) private String eventKey; @Column(name="is_read",nullable=false) private boolean read; @Column(name="read_at") private LocalDateTime readAt; @Column(name="created_at") private LocalDateTime createdAt;
 public Long getId(){return id;} public Long getUserId(){return userId;} public void setUserId(Long v){userId=v;} public String getType(){return type;} public void setType(String v){type=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getContent(){return content;} public void setContent(String v){content=v;} public String getResourceType(){return resourceType;} public void setResourceType(String v){resourceType=v;} public Long getResourceId(){return resourceId;} public void setResourceId(Long v){resourceId=v;} public String getEventKey(){return eventKey;} public void setEventKey(String v){eventKey=v;} public boolean isRead(){return read;} public void setRead(boolean v){read=v;} public LocalDateTime getReadAt(){return readAt;} public void setReadAt(LocalDateTime v){readAt=v;} public LocalDateTime getCreatedAt(){return createdAt;} public void setCreatedAt(LocalDateTime v){createdAt=v;}
}
